    cevap: "py_oyun ile ses çalabilirsin. Kısa ses efektleri için ses_yükle ve çal, uzun müzikler için müzik_yükle ve müzik_çal kullanılır. Ses dosyası (wav ya da mp3) programınla aynı klasörde olmalı.",
    kod: "içe_aktar py_oyun\npy_oyun.oyun_başlat()\nzil = py_oyun.ses_yükle(\"zil.wav\")\nzil.çal()\npy_oyun.müzik_yükle(\"sarki.mp3\")\npy_oyun.müzik_çal()",
